	@Test
	void singlePatternPreservesGraphIdentityMultiplicityAndSnapshot(@TempDir File directory) {
		var store = new LmdbStore(directory, new LmdbStoreConfig().setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var s = vf.createIRI("urn:s");
			var p = vf.createIRI("urn:p");
			var g = vf.createIRI("urn:g");
			var b = vf.createBNode("named-graph");
			connection.begin();
			for (var context : List.of(g, b, RDF4J.NIL)) {
				connection.add(s, p, s, context);
				connection.add(s, p, g, context);
			}
			connection.commit();

			var query = connection.prepareTupleQuery(POINT);
			assertThat(graphs(query)).containsExactlyInAnyOrder(g, g, b, b, RDF4J.NIL, RDF4J.NIL);
			query.setBinding("g", b);
			assertThat(graphs(query)).containsExactly(b, b);
			query.clearBindings();
			var shared = connection.prepareTupleQuery("SELECT ?g { GRAPH ?g { <urn:s> <urn:p> ?g } }");
			assertThat(graphs(shared)).containsExactly(g);

			connection.begin(IsolationLevels.SNAPSHOT);
			connection.clear(g);
			connection.add(s, p, vf.createLiteral("default-only"), (Resource) null);
			assertThat(graphs(query)).containsExactlyInAnyOrder(b, b, RDF4J.NIL, RDF4J.NIL);
			connection.commit();
			assertThat(graphs(query)).containsExactlyInAnyOrder(b, b, RDF4J.NIL, RDF4J.NIL);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void inferredPlaneAndExplicitDatasetRemainAuthoritative(@TempDir File directory) {
		var store = new LmdbStore(directory, new LmdbStoreConfig().setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var s = vf.createIRI("urn:s");
			var p = vf.createIRI("urn:p");
			var e = vf.createIRI("urn:explicit");
			var i = vf.createIRI("urn:inferred");
			connection.begin();
			connection.add(s, p, s, e);
			((LmdbStoreConnection) connection.getSailConnection()).addInferredStatement(s, p, s, i);
			connection.commit();
			var query = connection.prepareTupleQuery(POINT);
			query.setIncludeInferred(true);
			assertThat(graphs(query)).containsExactlyInAnyOrder(e, i);
			query.setIncludeInferred(false);
			assertThat(graphs(query)).containsExactly(e);
			var onlyInferredGraph = connection
					.prepareTupleQuery("SELECT ?g FROM NAMED <urn:inferred> { GRAPH ?g { <urn:s> <urn:p> ?o } }");
			assertThat(graphs(onlyInferredGraph)).containsExactly(i);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void pointLookupIsReportedUnderTelemetry(@TempDir File directory) {
		withPointData(directory, connection -> {
			var query = connection.prepareTupleQuery(POINT);
			// Telemetry turns on result-size tracking, runtime telemetry and the execution summary together.
			var graph = planNode(query.explain(Explanation.Level.Telemetry), "Graph");
			assertThat(graph.getStringMetricPlanned(GRAPH_LOOKUP)).isEqualTo("namedContextScanIfDefaultGraphEmpty");
			assertThat(graph.getStringMetricActual(GRAPH_LOOKUP)).isEqualTo(NAMED_CONTEXT_SCAN);
			assertThat(graph.getResultSizeActual()).isEqualTo(6);
			assertThat(planNode(query.explain(Explanation.Level.Optimized), "Graph")
					.getStringMetricPlanned(GRAPH_LOOKUP)).isEqualTo("namedContextScanIfDefaultGraphEmpty");
		});
	}

