	@Test
	void timedAndExecutedExplainReturnTheSameRows(@TempDir File directory) {
		withPointData(directory, connection -> {
			var query = connection.prepareTupleQuery(POINT);
			long expected = graphs(query).size();
			assertThat(expected).isEqualTo(6);
			for (var level : List.of(Explanation.Level.Executed, Explanation.Level.Timed)) {
				var graph = planNode(query.explain(level), "Graph");
				// Tracking rows or time must not turn the lookup off: the same plan is prepared at every level.
				assertThat(graph.getStringMetricPlanned(GRAPH_LOOKUP)).as("planned GRAPH lookup at %s", level)
						.isEqualTo("namedContextScanIfDefaultGraphEmpty");
				// The row count of the lookup belongs on the visible body, whichever physical plan produced it.
				assertThat(graph.getResultSizeActual()).as("GRAPH rows at %s", level).isEqualTo(expected);
				var body = planNode(graph, "StatementPattern");
				assertThat(body.getResultSizeActual()).as("body rows at %s", level).isEqualTo(expected);
				if (level == Explanation.Level.Timed) {
					assertThat(body.getTotalTimeActual()).as("body time").isNotNull();
				}
			}
		});
	}

