	@ParameterizedTest
	@ValueSource(strings = { "SELECT ?h ?g { GRAPH ?h { GRAPH ?g { <urn:s> <urn:p> ?o } } }",
			"SELECT ?h ?g { GRAPH ?h { { SELECT ?g { GRAPH ?g { <urn:s> <urn:p> ?o } } } } }" })
	void variableGraphBelowAnotherGraphKeepsItsBagOnTheGenericStep(String nested, @TempDir File directory) {
		withPointData(directory, connection -> {
			var query = connection.prepareTupleQuery(nested);
			List<List<Value>> expected = new ArrayList<>();
			for (Value outer : List.of(G, B, RDF4J.NIL)) {
				for (Value inner : List.of(G, G, B, B, RDF4J.NIL, RDF4J.NIL)) {
					expected.add(List.of(outer, inner));
				}
			}
			assertThat(rows(query, "h", "g")).containsExactlyInAnyOrderElementsOf(expected);
			List<GenericPlanNode> graphs = new ArrayList<>();
			collectPlanNodes(query.explain(Explanation.Level.Telemetry).toGenericPlanNode(), "Graph", graphs);
			assertThat(graphs).hasSize(2)
					.allSatisfy(graph -> assertThat(graph.getStringMetricPlanned(GRAPH_LOOKUP)).isNull());
		});
	}

