	@Test
	void graphPointChoosesWithoutRecompiling() {
		var validations = new AtomicInteger();
		var defaultGraphChecks = new AtomicInteger();
		var defaultGraphEmpty = new AtomicBoolean(true);
		List<BindingSet> quadInputs = new ArrayList<>();
		List<BindingSet> ordinaryInputs = new ArrayList<>();
		List<String> choices = new ArrayList<>();
		// The chooser receives prepared steps, so it has nothing to compile on any evaluation.
		QueryEvaluationStep quad = input -> {
			quadInputs.add(input);
			return new EmptyIteration<>();
		};
		QueryEvaluationStep ordinary = input -> {
			ordinaryInputs.add(input);
			return new EmptyIteration<>();
		};
		QueryEvaluationStep step = LmdbEvaluationStrategy.graphPoint(validations::incrementAndGet, () -> {
			defaultGraphChecks.incrementAndGet();
			return defaultGraphEmpty.get();
		}, quad, ordinary, choices::add);

		var emptyRow = new MapBindingSet();
		try (var unopened = step.evaluate(emptyRow)) {
			// Store work waits for demand.
			assertThat(validations).hasValue(0);
		}
		drain(step.evaluate(EmptyBindingSet.getInstance()));
		drain(step.evaluate(emptyRow));
		assertThat(quadInputs).hasSize(2);
		assertThat(quadInputs.get(0)).isSameAs(EmptyBindingSet.getInstance());
		assertThat(quadInputs.get(1)).isSameAs(emptyRow);
		assertThat(ordinaryInputs).isEmpty();
		assertThat(validations).hasValue(2);
		assertThat(defaultGraphChecks).hasValue(2);
		assertThat(choices).containsExactly(NAMED_CONTEXT_SCAN, NAMED_CONTEXT_SCAN);

		// Any binding, also one the GRAPH pattern never mentions, keeps the row on the generic step.
		var boundRow = new MapBindingSet();
		boundRow.setBinding("unrelated", S);
		drain(step.evaluate(boundRow));
		// So does an empty row that carries evaluation-frame provenance.
		var framedRow = new QueryBindingSet();
		GraphFrameBindings.markSiblingInputCleared(framedRow, 1L, "g");
		assertThat(framedRow.isEmpty()).isTrue();
		drain(step.evaluate(framedRow));
		assertThat(ordinaryInputs).hasSize(2);
		assertThat(ordinaryInputs.get(0)).isSameAs(boundRow);
		assertThat(ordinaryInputs.get(1)).isSameAs(framedRow);
		assertThat(quadInputs).hasSize(2);
		assertThat(validations).hasValue(2);
		assertThat(choices).hasSize(2);

		// The default-graph answer is asked again on every evaluation, after validation.
		defaultGraphEmpty.set(false);
		drain(step.evaluate(emptyRow));
		assertThat(ordinaryInputs).hasSize(3);
		assertThat(ordinaryInputs.get(2)).isSameAs(emptyRow);
		assertThat(quadInputs).hasSize(2);
		assertThat(validations).hasValue(3);
		assertThat(defaultGraphChecks).hasValue(3);
		assertThat(choices).containsExactly(NAMED_CONTEXT_SCAN, NAMED_CONTEXT_SCAN, "catalogEnumeration");

		defaultGraphEmpty.set(true);
		drain(step.evaluate(emptyRow));
		assertThat(quadInputs).hasSize(3);
		assertThat(validations).hasValue(4);
		assertThat(defaultGraphChecks).hasValue(4);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void closeOrCancelWhileOpeningNeverPullsTheNewChild(boolean cancel) throws Exception {
		var opening = new CountDownLatch(1);
		var resume = new CountDownLatch(1);
		var pulls = new AtomicInteger();
		var closes = new AtomicInteger();
		try (var executor = Executors.newSingleThreadExecutor();
				var rows = LmdbEvaluationStrategy.demandGraphLookup(input -> {
					opening.countDown();
					try {
						if (!resume.await(10, TimeUnit.SECONDS)) {
							throw new AssertionError("opener was not released");
						}
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new AssertionError(e);
					}
					return new CloseableIteration<BindingSet>() {
						@Override
						public boolean hasNext() {
							pulls.incrementAndGet();
							return false;
						}

						@Override
						public BindingSet next() {
							throw new AssertionError();
						}

						@Override
						public void remove() {
							throw new UnsupportedOperationException();
						}

						@Override
						public void close() {
							closes.incrementAndGet();
						}
					};
				}, EmptyBindingSet.getInstance())) {
			var first = executor.submit(rows::hasNext);
			try {
				assertThat(opening.await(10, TimeUnit.SECONDS)).isTrue();
				if (cancel) {
					assertThat(CooperativeCancellation.forward(rows)).isTrue();
				} else {
					rows.close();
				}
			} finally {
				resume.countDown();
			}
			assertThat(first.get(10, TimeUnit.SECONDS)).isFalse();
			assertThat(pulls).hasValue(0);
			assertThat(closes).hasValue(1);
		}
	}

	/** Three named graphs, one of them a blank node and one the physical nil graph; the default graph stays empty. */
	private static void withPointData(File directory, Consumer<SailRepositoryConnection> scenario) {
		var repository = new SailRepository(new LmdbStore(directory,
				new LmdbStoreConfig().setNativeEvaluationEnabled(false).setDirectAdjacencyEnabled(false)));
		try (var connection = repository.getConnection()) {
			connection.begin();
			for (var context : List.of(G, B, RDF4J.NIL)) {
				connection.add(S, P, S, context);
				connection.add(S, P, G, context);
			}
			// Selector candidates for a join: an IRI graph, a blank-node graph and a name that is no graph.
			for (var selector : List.of(G, B, S)) {
				connection.add(selector, Q, S, G);
			}
			connection.commit();
			scenario.accept(connection);
		} finally {
			repository.shutDown();
		}
	}

	private static GenericPlanNode planNode(Explanation explanation, String type) {
		return planNode(explanation.toGenericPlanNode(), type);
	}

	private static GenericPlanNode planNode(GenericPlanNode root, String type) {
		GenericPlanNode found = findPlanNode(root, type);
		assertThat(found).as("%s node in%n%s", type, root).isNotNull();
		return found;
	}

	private static GenericPlanNode findPlanNode(GenericPlanNode node, String type) {
		if (node.getType().startsWith(type)) {
			return node;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				GenericPlanNode found = findPlanNode(child, type);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}

	private static void collectPlanNodes(GenericPlanNode node, String type, List<GenericPlanNode> found) {
		if (node.getType().startsWith(type)) {
			found.add(node);
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collectPlanNodes(child, type, found));
		}
	}

	private static void drain(CloseableIteration<BindingSet> rows) {
		try (rows) {
			while (rows.hasNext()) {
				rows.next();
			}
		}
	}

	private static List<List<Value>> rows(TupleQuery query, String first, String second) {
		List<List<Value>> saved = new ArrayList<>();
		try (var rows = query.evaluate()) {
			while (rows.hasNext()) {
				BindingSet row = rows.next();
				saved.add(List.of(row.getValue(first), row.getValue(second)));
			}
		}
		return saved;
	}

	private static List<Value> graphs(TupleQuery query) {
		List<BindingSet> saved = new ArrayList<>();
		try (var rows = query.evaluate()) {
			while (rows.hasNext()) {
				saved.add(rows.next());
			}
		}
		return saved.stream().map(row -> row.getValue("g")).toList();
	}
